'use client';

import * as React from 'react';
import { Icon16Clear, Icon16SearchOutline, Icon24Cancel } from '@vkontakte/icons';
import { classNames, hasReactNode, noop } from '@vkontakte/vkjs';
import { useAdaptivity } from '../../hooks/useAdaptivity';
import { useAdaptivityConditionalRender } from '../../hooks/useAdaptivityConditionalRender';
import { useBooleanState } from '../../hooks/useBooleanState';
import { useConfigDirection } from '../../hooks/useConfigDirection';
import { useExternRef } from '../../hooks/useExternRef';
import { useMergeProps } from '../../hooks/useMergeProps';
import { useNativeFormResetListener } from '../../hooks/useNativeFormResetListener';
import { usePlatform } from '../../hooks/usePlatform';
import { callMultiple } from '../../lib/callMultiple';
import { getActiveElementByAnotherElement } from '../../lib/dom';
import { touchEnabled } from '../../lib/touch';
import { useIsomorphicLayoutEffect } from '../../lib/useIsomorphicLayoutEffect';
import { warnOnce } from '../../lib/warnOnce';
import type { HasDataAttribute, HasRootRef } from '../../types';
import { Button } from '../Button/Button';
import { IconButton, type IconButtonProps } from '../IconButton/IconButton';
import { RootComponent } from '../RootComponent/RootComponent';
import { Headline } from '../Typography/Headline/Headline';
import { VisuallyHidden } from '../VisuallyHidden/VisuallyHidden';
import styles from './Search.module.css';

const warn = warnOnce('Search');

export type RenderIconButtonFn = (
  icon: React.ReactNode,
  props?: (Partial<IconButtonProps> & HasDataAttribute) | undefined,
) => React.ReactElement;

export interface SearchProps
  extends Pick<
      React.InputHTMLAttributes<HTMLInputElement>,
      | 'autoComplete'
      | 'autoCapitalize'
      | 'autoCorrect'
      | 'disabled'
      | 'list'
      | 'maxLength'
      | 'minLength'
      | 'name'
      | 'pattern'
      | 'enterKeyHint'
      | 'placeholder'
      | 'readOnly'
      | 'required'
      | 'value'
      | 'form'
      | 'onChange'
      | 'onFocus'
      | 'onBlur'
    >,
    Omit<React.HTMLAttributes<HTMLDivElement>, 'onChange' | 'onFocus' | 'onBlur'>,
    HasRootRef<HTMLDivElement> {
  /**
   * @deprecated Since 7.9.0. Вместо этого используйте `slotProps={ input: { getRootRef: ... } }`.
   */
  getRef?: React.Ref<HTMLInputElement> | undefined;
  /**
   * Свойства, которые можно прокинуть внутрь компонента:
   * - `root`: свойства для прокидывания в корень компонента;
   * - `input`: свойства для прокидывания в поле ввода;
   * - `clearButton`: свойства для прокидывания в кнопку очистки.
   */
  slotProps?:
    | {
        root?:
          | (React.HTMLAttributes<HTMLDivElement> & HasRootRef<HTMLDivElement> & HasDataAttribute)
          | undefined;
        input?: React.InputHTMLAttributes<HTMLInputElement> &
          HasRootRef<HTMLInputElement> &
          HasDataAttribute;
        clearButton?: React.HTMLAttributes<HTMLElement> &
          HasRootRef<HTMLElement> &
          HasDataAttribute;
      }
    | undefined;
  /**
   * Only iOS. Текст кнопки "отмена", которая чистит текстовое поле и убирает фокус.
   */
  after?: React.ReactNode | undefined;
  /**
   * Контент, отображаемый перед полем ввода.
   */
  before?: React.ReactNode | undefined;
  /**
   * Иконка поиска. Может быть React-элементом или функцией, возвращающей элемент.
   */
  icon?: React.ReactNode | ((renderFn: RenderIconButtonFn) => React.ReactNode) | undefined;
  /**
   * Обработчик нажатия на иконку поиска.
   */
  onIconClick?: React.PointerEventHandler<HTMLElement> | undefined;
  /**
   * Значение поля ввода по умолчанию.
   */
  defaultValue?: string | undefined;
  /**
   * Текст для скринридеров, описывающий иконку поиска.
   */
  iconLabel?: string | undefined;
  /**
   * Текст для скринридеров, описывающий кнопку очистки.
   */
  clearLabel?: string | undefined;
  /**
   * @deprecated Since 8.1.0. Будет удалено в **VKUI v10**. Вместо этого используйте `slotProps={ clearButton: { 'data-testid': ... } }`.
   *
   * Передает атрибут `data-testid` для кнопки очистки.
   */
  clearButtonTestId?: string | undefined;
  /**
   * Удаляет отступы у компонента.
   */
  noPadding?: boolean | undefined;
  /**
   * Текст для кнопки Найти.
   */
  findButtonText?: string | undefined;
  /**
   * Обработчик, при нажатии на кнопку "Найти".
   */
  onFindButtonClick?: React.MouseEventHandler<HTMLElement> | undefined;
  /**
   * Передает атрибут `data-testid` для кнопки поиска.
   */
  findButtonTestId?: string | undefined;
  /**
   * Скрывает кнопку очистки.
   */
  hideClearButton?: boolean | undefined;
}

/**
 * @see https://vkui.io/components/search
 */
export const Search = ({
  // SearchProps
  after = 'Отмена',
  before = <Icon16SearchOutline />,
  icon: iconProp,
  onIconClick,
  iconLabel,
  clearLabel = 'Очистить',
  clearButtonTestId,
  noPadding,
  findButtonText = 'Найти',
  onFindButtonClick,
  findButtonTestId,
  hideClearButton,
  getRef,

  // input props
  autoComplete = 'off',
  autoCapitalize,
  autoCorrect,
  disabled,
  list,
  maxLength,
  minLength,
  name,
  pattern,
  placeholder: placeholderProp = 'Поиск',
  enterKeyHint,
  readOnly,
  required,
  value,
  form,
  id: idProp,
  inputMode,
  defaultValue,
  autoFocus,
  tabIndex,
  spellCheck,
  onChange: onChangeProp,
  onFocus: onFocusProp,
  onBlur: onBlurProp,

  slotProps,
  ...restProps
}: SearchProps): React.ReactNode => {
  /* istanbul ignore if: не проверяем в тестах */
  if (process.env.NODE_ENV === 'development') {
    if (getRef) {
      warn('Свойство `getRef` устаревшее, используйте `slotProps={ input: { getRootRef: ... } }`');
    }
    if (clearButtonTestId) {
      warn(
        "Свойство `clearButtonTestId` устаревшее, используйте `slotProps={ clearButton: { 'data-testid': ... } }`",
      );
    }
  }

  const direction = useConfigDirection();
  const isRtl = direction === 'rtl';

  const rootRest = useMergeProps(restProps, slotProps?.root);

  const {
    id,
    placeholder,
    getRootRef: getInputRef,
    onChange,
    onFocus: onInputFocus,
    onBlur: onInputBlur,
    ...inputRest
  } = useMergeProps(
    {
      getRootRef: getRef,
      className: styles.nativeInput,
      placeholder: placeholderProp,
      autoComplete,
      autoCapitalize,
      autoCorrect,
      disabled,
      list,
      maxLength,
      minLength,
      name,
      pattern,
      enterKeyHint,
      readOnly,
      required,
      value,
      form,
      id: idProp,
      inputMode,
      defaultValue,
      autoFocus,
      tabIndex,
      spellCheck,
      onChange: onChangeProp,
      onFocus: onFocusProp,
      onBlur: onBlurProp,
    },
    slotProps?.input,
  );

  const {
    onClick: onClearButtonClick,
    onPointerDown: onClearButtonPointerDown,
    getRootRef: getClearButtonRef,
    ...clearButtonRest
  } = useMergeProps({ className: styles.icon }, slotProps?.clearButton);

  const inputRef = useExternRef(getInputRef);
  const clearButtonRef = useExternRef(getClearButtonRef);
  const findButtonRef = React.useRef<HTMLElement>(null);
  const [isFocused, setFocusedTrue, setFocusedFalse] = useBooleanState(false);
  const generatedId = React.useId();
  const inputId = id ? id : `search-${generatedId}`;

  const [hasValue, setHasValue] = React.useState<boolean>(() =>
    Boolean(inputRest.value || inputRest.defaultValue),
  );
  const checkHasValue: React.ChangeEventHandler<HTMLInputElement> = (e) =>
    setHasValue(Boolean(e.currentTarget.value));

  const { density = 'none' } = useAdaptivity();
  const { density: adaptiveDensity } = useAdaptivityConditionalRender();
  const platform = usePlatform();

  const hasAfter = platform === 'ios' && hasReactNode(after);

  const onFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    setFocusedTrue();
    onInputFocus && onInputFocus(e);
  };

  const onBlur = (e: React.FocusEvent<HTMLInputElement>) => {
    setFocusedFalse();
    onInputBlur && onInputBlur(e);
  };

  const onCancel = React.useCallback(() => {
    // eslint-disable-next-line @typescript-eslint/unbound-method
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
      HTMLInputElement.prototype,
      'value',
    )?.set;
    nativeInputValueSetter?.call(inputRef.current, '');

    const ev2 = new Event('input', { bubbles: true });
    inputRef.current?.dispatchEvent(ev2);
  }, [inputRef]);

  const onIconClickStart: React.PointerEventHandler<HTMLElement> = React.useCallback(
    (e) => onIconClick?.(e),
    [onIconClick],
  );

  useIsomorphicLayoutEffect(() => {
    if (inputRest.value !== undefined) {
      setHasValue(Boolean(inputRest.value));
    }
  }, [inputRest.value]);

  useNativeFormResetListener(inputRef, () => {
    setHasValue(Boolean(inputRest.defaultValue));
  });

  // Без значения кнопки скрыты от скринридера, поэтому фокус с них переводим в поле
  useIsomorphicLayoutEffect(() => {
    if (hasValue) {
      return;
    }
    const activeElement = getActiveElementByAnotherElement(inputRef.current);
    if (
      activeElement &&
      (activeElement === clearButtonRef.current || activeElement === findButtonRef.current)
    ) {
      inputRef.current?.focus();
    }
  }, [hasValue]);

  const renderIconButton: RenderIconButtonFn = (icon, props = {}) => (
    <IconButton
      hoverMode="opacity"
      onPointerDown={onIconClickStart}
      className={styles.icon}
      onFocus={setFocusedTrue}
      onBlur={setFocusedFalse}
      onClick={noop}
      {...props}
    >
      <VisuallyHidden>{iconLabel}</VisuallyHidden>
      {icon}
    </IconButton>
  );

  const showControls = Boolean(
    iconProp || !hideClearButton || (adaptiveDensity.compact && onFindButtonClick),
  );

  const onClearPointerDown: React.PointerEventHandler<HTMLElement> = (e) => {
    // Сначала вызываем внешний обработчик, затем локальную логику, чтобы можно было предотвратить обработку фокуса на поле ввода.
    onClearButtonPointerDown?.(e);

    e.preventDefault();
    inputRef.current?.focus();
    if (touchEnabled()) {
      onCancel();
    }
  };

  const onClearClick: React.MouseEventHandler<HTMLElement> = (e) => {
    // eslint-disable-next-line @typescript-eslint/unbound-method
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
      HTMLInputElement.prototype,
      'value',
    )?.set;
    nativeInputValueSetter?.call(inputRef.current, '');

    const ev2 = new Event('input', { bubbles: true });
    inputRef.current?.dispatchEvent(ev2);

    onClearButtonClick?.(e);
  };

  return (
    <RootComponent
      baseClassName={classNames(
        'vkuiInternalSearch',
        styles.host,
        density === 'none' && styles.densityNone,
        density === 'compact' && styles.densityCompact,
        isFocused && styles.focused,
        hasValue && styles.hasValue,
        hasAfter && styles.hasAfter,
        iconProp && styles.hasIcon,
        inputRest.disabled && styles.disabled,
        !noPadding && styles.withPadding,
        isRtl && styles.rtl,
      )}
      {...rootRest}
    >
      <div className={styles.field}>
        <label htmlFor={inputId} className={styles.label}>
          {placeholder}
        </label>
        <div className={styles.input}>
          {before}
          <Headline
            Component="input"
            type="search"
            level="1"
            weight="3"
            id={inputId}
            placeholder={placeholder}
            getRootRef={inputRef}
            onChange={callMultiple(onChange, checkHasValue)}
            onFocus={onFocus}
            onBlur={onBlur}
            {...inputRest}
          />
        </div>
        {showControls && (
          <div className={styles.controls}>
            {iconProp &&
              (typeof iconProp === 'function'
                ? iconProp(renderIconButton)
                : renderIconButton(iconProp))}
            {!hideClearButton && (
              <IconButton
                hoverMode="opacity"
                onPointerDown={onClearPointerDown}
                getRootRef={clearButtonRef}
                onClick={onClearClick}
                tabIndex={hasValue ? undefined : -1}
                aria-hidden={hasValue ? undefined : true}
                disabled={inputRest.disabled}
                data-testid={clearButtonTestId}
                {...clearButtonRest}
              >
                <VisuallyHidden>{clearLabel}</VisuallyHidden>
                {platform === 'ios' ? <Icon16Clear /> : <Icon24Cancel />}
              </IconButton>
            )}
            {adaptiveDensity.compact && onFindButtonClick && (
              <Button
                mode="primary"
                size="m"
                className={classNames(styles.findButton, adaptiveDensity.compact.className)}
                focusVisibleMode="inside"
                getRootRef={findButtonRef}
                onClick={onFindButtonClick}
                tabIndex={hasValue ? undefined : -1}
                aria-hidden={hasValue ? undefined : true}
                data-testid={findButtonTestId}
              >
                {findButtonText}
              </Button>
            )}
          </div>
        )}
      </div>
      {hasAfter && (
        <div className={styles.after}>
          <Button
            mode="tertiary"
            size="m"
            focusVisibleMode="inside"
            hoverMode="opacity"
            activeMode="opacity"
            onClick={onCancel}
            onFocus={setFocusedTrue}
            onBlur={setFocusedFalse}
          >
            {after}
          </Button>
        </div>
      )}
    </RootComponent>
  );
};
